parameters.jsCode:
const items = $input.all();

return items.map(item => {
  const input = item.json;

  const results = input.results || [];
  const entities = input.entities || [];

  // ---------------------------------------------------------
  // ORIGINAL COMPANY DATA FROM MERGE
  // ---------------------------------------------------------

  const originalCompany =
    input.company || {};

  // Original company name from Prospeo/Search Company
  const originalCompanyName =
    originalCompany.name || null;

  // Original company domain from Prospeo/Search Company
  const originalCompanyDomain =
    originalCompany.domain || null;

  // ---------------------------------------------------------
  // EXA COMPANY ENTITY
  // ---------------------------------------------------------

  const companyEntity = entities.find(
    entity => entity.type === "company"
  );

  const properties = companyEntity?.properties || {};

  // IMPORTANT:
  // Always prefer the original company name.
  // Never use result.author as a company name.
  const companyName =
    originalCompanyName ||
    properties.name ||
    null;

  const companyDomain =
    originalCompanyDomain ||
    null;

  const companyDescription =
    properties.description || "";

  const workforce =
    companyEntity?.workforce?.total ?? null;

  const country =
    companyEntity?.headquarters?.country || null;

  // ---------------------------------------------------------
  // COMBINE EXA EVIDENCE
  // ---------------------------------------------------------

  const evidenceText = results
    .map(result => {
      return [
        result.title || "",
        ...(result.highlights || [])
      ].join(" ");
    })
    .join(" ")
    .toLowerCase();

  const descriptionText =
    companyDescription.toLowerCase();

  const allText =
    `${evidenceText} ${descriptionText}`;

  // ---------------------------------------------------------
  // SIGNAL SCORING FUNCTION
  // ---------------------------------------------------------

  function signalScore(patterns, strongPatterns = []) {
    const strongMatch = strongPatterns.some(pattern =>
      pattern.test(allText)
    );

    if (strongMatch) return 3;

    const matches = patterns.filter(pattern =>
      pattern.test(allText)
    ).length;

    if (matches >= 2) return 2;
    if (matches === 1) return 1;

    return 0;
  }

  // ---------------------------------------------------------
  // B2B FIT
  // ---------------------------------------------------------

  let b2bFit = 0;

  if (
    /business(es)?|enterprise|organizations?|clients?|companies?|b2b|business customers/i.test(
      allText
    )
  ) {
    b2bFit = 2;
  }

  if (
    /enterprise solutions|business solutions|business customers|b2b|serves organizations/i.test(
      allText
    )
  ) {
    b2bFit = 3;
  }

  // ---------------------------------------------------------
  // FUNDING
  // ---------------------------------------------------------

  const funding = signalScore(
    [
      /funding/i,
      /raised/i,
      /investment/i,
      /investor/i,
      /seed round/i,
      /series [a-z]/i
    ],
    [
      /recently raised/i,
      /latest funding/i,
      /funding round/i,
      /series [a-z].{0,30}(million|funding|raised)/i
    ]
  );

  // ---------------------------------------------------------
  // HIRING
  // ---------------------------------------------------------

  const hiring = signalScore(
    [
      /we('re| are) hiring/i,
      /hiring/i,
      /open positions/i,
      /job postings/i,
      /new joiner/i,
      /joined us/i
    ],
    [
      /active job postings:\s*[1-9]/i,
      /aggressive hiring/i,
      /rapid hiring/i,
      /multiple.*open positions/i
    ]
  );

  // ---------------------------------------------------------
  // JOB CHANGES / NEW HIRES / PROMOTIONS
  // ---------------------------------------------------------

  const jobChanges = signalScore(
    [
      /joined us/i,
      /new joiner/i,
      /new hire/i,
      /promoted/i,
      /promotion/i,
      /appointed/i,
      /departed/i,
      /left the company/i
    ],
    [
      /senior.*joined/i,
      /executive.*joined/i,
      /promoted to/i,
      /appointed as/i
    ]
  );

  // ---------------------------------------------------------
  // LEADERSHIP
  // ---------------------------------------------------------

  const leadership = signalScore(
    [
      /ceo/i,
      /coo/i,
      /cmo/i,
      /cto/i,
      /chief executive/i,
      /chief operating/i,
      /vp marketing/i,
      /head of growth/i,
      /head of marketing/i,
      /leadership/i
    ],
    [
      /new ceo/i,
      /new coo/i,
      /new cmo/i,
      /new cto/i,
      /vp marketing/i,
      /head of growth/i,
      /appointed.*chief/i,
      /hiring.*vp/i
    ]
  );

  // ---------------------------------------------------------
  // RAPID GROWTH
  // ---------------------------------------------------------

  const rapidGrowth = signalScore(
    [
      /growth/i,
      /growing/i,
      /grew/i,
      /expanded/i,
      /expansion/i,
      /employee.*growth/i,
      /workforce.*growth/i
    ],
    [
      /\+\d+(?:\.\d+)?%.*yoy/i,
      /rapidly growing/i,
      /fast-growing/i,
      /significant growth/i
    ]
  );

  // ---------------------------------------------------------
  // EXPANSION
  // ---------------------------------------------------------

  const expansion = signalScore(
    [
      /expanded/i,
      /expansion/i,
      /new market/i,
      /new location/i,
      /new office/i,
      /global presence/i,
      /international/i
    ],
    [
      /expanded.*market/i,
      /entered.*market/i,
      /new office/i,
      /presence in.*countries/i
    ]
  );

  // ---------------------------------------------------------
  // TECHNOLOGY / SYSTEM CHANGE
  // ---------------------------------------------------------

  const technologyChange = signalScore(
    [
      /technology/i,
      /software/i,
      /platform/i,
      /automation/i,
      /ai-assisted/i,
      /ai/i,
      /crm/i,
      /hrms/i,
      /tech stack/i
    ],
    [
      /adopted.*technology/i,
      /implemented.*system/i,
      /new.*platform/i,
      /ai-assisted/i,
      /automation/i
    ]
  );

  // ---------------------------------------------------------
  // NEW BUSINESS LANE
  // ---------------------------------------------------------

  const newBusinessLane = signalScore(
    [
      /new service/i,
      /new product/i,
      /new business/i,
      /new offering/i,
      /digital transformation/i,
      /software development/i,
      /business expansion/i
    ],
    [
      /launch(ed|ing).*product/i,
      /launch(ed|ing).*service/i,
      /new business line/i,
      /expanded.*services/i
    ]
  );

  // ---------------------------------------------------------
  // WEBSITE / PRODUCT INTENT
  // ---------------------------------------------------------

  const websiteProductIntent = signalScore(
    [
      /product/i,
      /platform/i,
      /solution/i,
      /services/i,
      /digital/i,
      /technology/i
    ],
    [
      /launch(ed|ing).*product/i,
      /new.*platform/i,
      /new.*solution/i
    ]
  );

  // ---------------------------------------------------------
  // CUSTOMER SENTIMENT
  // ---------------------------------------------------------

  const customerSentiment = signalScore(
    [
      /customer reviews/i,
      /client feedback/i,
      /testimonials/i,
      /customer satisfaction/i,
      /rated/i,
      /reviews/i
    ],
    [
      /positive customer/i,
      /excellent reviews/i,
      /highly rated/i,
      /5 out of 5/i
    ]
  );

  // ---------------------------------------------------------
  // NEGATIVE ISSUES
  // ---------------------------------------------------------

  const negativeIssues = signalScore(
    [
      /complaint/i,
      /negative review/i,
      /poor review/i,
      /issue/i,
      /problem/i,
      /concern/i,
      /negative feedback/i
    ],
    [
      /customer complaints/i,
      /repeated complaints/i,
      /serious issue/i,
      /negative customer feedback/i
    ]
  );

  // ---------------------------------------------------------
  // COMPANY NEWS
  // ---------------------------------------------------------

  const companyNews = signalScore(
    [
      /announced/i,
      /announcement/i,
      /news/i,
      /conference/i,
      /event/i,
      /partnership/i,
      /networking/i
    ]
  );

  // ---------------------------------------------------------
  // WEIGHTS
  // ---------------------------------------------------------

  const weights = {
    b2bFit: 15,
    funding: 15,
    hiring: 15,
    jobChanges: 10,
    leadership: 12,
    rapidGrowth: 12,
    expansion: 7,
    technologyChange: 5,
    newBusinessLane: 5,
    websiteProductIntent: 3,
    customerSentiment: 1,
    negativeIssues: 0,
    companyNews: 0
  };

  // ---------------------------------------------------------
  // SCORES
  // ---------------------------------------------------------

  const scores = {
    b2bFit,
    funding,
    hiring,
    jobChanges,
    leadership,
    rapidGrowth,
    expansion,
    technologyChange,
    newBusinessLane,
    websiteProductIntent,
    customerSentiment,
    negativeIssues,
    companyNews
  };

  // ---------------------------------------------------------
  // WEIGHTED TOTAL
  // ---------------------------------------------------------

  let weightedTotal = 0;
  let maximumPossible = 0;

  for (const key of Object.keys(weights)) {
    weightedTotal +=
      (scores[key] / 3) * weights[key];

    maximumPossible += weights[key];
  }

  const overallScore = Math.round(
    (weightedTotal / maximumPossible) * 100
  );

  // ---------------------------------------------------------
  // FINAL OUTPUT
  // ---------------------------------------------------------

 return {
  json: {
    company_id: originalCompany.company_id || null,
    company_name: companyName,
    company_domain: companyDomain,
    linkedin_url: originalCompany.linkedin_url || null,
    company_country: country,
    workforce,

    signals: scores,

    overall_score: overallScore,

    evidence: results.map(result => ({
      title: result.title || null,
      url: result.url || null,
      publishedDate: result.publishedDate || null,
      highlights: result.highlights || []
    }))
  }
};
});

