={
  "query": "Find the current Founder, Co-Founder, Owner, CEO, Chief Executive Officer, Managing Director, or President of {{ $json.company_name }}. Company LinkedIn page: {{ $json.linkedin_url }}. Return their full name, current job title, and personal LinkedIn profile URL. Only return people who currently work at this company. Do not invent information.",
  "numResults": 5,
  "type": "auto",
  "includeDomains": [
    "linkedin.com"
  ]
}

parameters.jsCode:
const output = [];

for (const item of $input.all()) {
  const r = item.json;

  const url = r.url || '';

  // Keep only personal LinkedIn profiles
  if (!url.includes('linkedin.com/in/')) {
    continue;
  }

  output.push({
    json: {
      person_name: r.title || null,
      linkedin_url: url
    }
  });
}

return output;

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const data = item.json;
  const person = data.person || {};

  const linkedin = String(
    person.linkedin_url || data.linkedin_url || ''
  )
    .trim()
    .toLowerCase()
    .replace(/\/$/, '');

  const email = String(
    person.email || data.email || ''
  )
    .trim()
    .toLowerCase();

  const name = String(
    person.full_name || data.person_name || ''
  )
    .trim()
    .toLowerCase();

  const company = String(
    data.company?.company_name ||
    data.company?.name ||
    data.company_name ||
    ''
  )
    .trim()
    .toLowerCase();

  let key;

  if (linkedin) {
    key = `linkedin:${linkedin}`;
  } else if (email) {
    key = `email:${email}`;
  } else if (name && company) {
    key = `name_company:${name}|${company}`;
  } else {
    key = `unique:${output.length}`;
  }

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);
  output.push(item);
}

return output;

